templates.body:
{%- assign title = scenario.names.exercise | default: scenario.name -%}
<h1>{{ title }}</h1>
<p>The design of {{ scenario.name }}, a {{ kind.name }} scenario, for its designers. Everything decided so far is here, with who decided it and why.</p>
{%- if scenario.scenario.executiveSummary %}

<h2>Executive Summary</h2>
<p>{{ scenario.scenario.executiveSummary }}</p>
{%- endif %}
{%- if scenario.engagement %}

<h2>Engagement</h2>
<table>
{%- if scenario.engagement.participants %}<tr><th>{{ labels.participants }}</th><td>{{ scenario.engagement.participants }}</td></tr>{% endif %}
{%- if scenario.engagement.headcount %}<tr><th>{{ labels.headcount }}</th><td>{{ scenario.engagement.headcount }}</td></tr>{% endif %}
{%- if scenario.engagement.timeSlot %}<tr><th>{{ labels.timeSlot }}</th><td>{{ scenario.engagement.timeSlot }}</td></tr>{% endif %}
{%- if scenario.engagement.audienceType %}<tr><th>{{ labels.audienceType }}</th><td>{{ scenario.engagement.audienceType }}</td></tr>{% endif %}
{%- if scenario.engagement.world %}<tr><th>{{ labels.world }}</th><td>{{ scenario.engagement.world }}</td></tr>{% endif %}
{%- if scenario.engagement.plainEnglish %}<tr><th>{{ labels.plainEnglish }}</th><td>{{ scenario.engagement.plainEnglish }}</td></tr>{% endif %}
{%- if scenario.engagement.scopeDocuments %}<tr><th>{{ labels.scopeDocuments }}</th><td>{{ scenario.engagement.scopeDocuments }}</td></tr>{% endif %}
{%- if scenario.engagement.sourceLimits %}<tr><th>{{ labels.sourceLimits }}</th><td>{{ scenario.engagement.sourceLimits }}</td></tr>{% endif %}
{%- if scenario.engagement.recording %}<tr><th>{{ labels.recording }}</th><td>{{ scenario.engagement.recording }}</td></tr>{% endif %}
{%- if scenario.engagement.complements %}<tr><th>{{ labels.complements }}</th><td>{{ scenario.engagement.complements }}</td></tr>{% endif %}
{%- if scenario.engagement.outputsFed %}<tr><th>{{ labels.outputsFed }}</th><td>{{ scenario.engagement.outputsFed }}</td></tr>{% endif %}
{%- if scenario.engagement.framework %}<tr><th>{{ labels.framework }}</th><td>{{ scenario.engagement.framework }}</td></tr>{% endif %}
</table>
{%- endif %}
{%- if scenario.objectives %}

<h2>Objectives</h2>
<ol>
{%- for o in scenario.objectives %}
<li><strong>{{ o.id }}</strong> {{ o.text }}</li>
{%- endfor %}
</ol>
{%- endif %}
{%- if scenario.teachingPoints %}

<h2>Teaching Points</h2>
<ul>
{%- for t in scenario.teachingPoints %}
<li>{{ t.text }}</li>
{%- endfor %}
</ul>
{%- endif %}
{%- if scenario.scenario %}

<h2>Premise</h2>
<table>
{%- if scenario.scenario.problem %}<tr><th>{{ labels.problem }}</th><td>{{ scenario.scenario.problem }}</td></tr>{% endif %}
{%- if scenario.scenario.obviousExplanation %}<tr><th>{{ labels.obviousExplanation }}</th><td>{{ scenario.scenario.obviousExplanation }}</td></tr>{% endif %}
{%- if scenario.scenario.actorType %}<tr><th>{{ labels.actorType }}</th><td>{{ scenario.scenario.actorType }}</td></tr>{% endif %}
{%- if scenario.scenario.motive %}<tr><th>{{ labels.motive }}</th><td>{{ scenario.scenario.motive }}</td></tr>{% endif %}
{%- if scenario.scenario.attackPath %}<tr><th>{{ labels.attackPath }}</th><td>{{ scenario.scenario.attackPath }}</td></tr>{% endif %}
{%- if scenario.scenario.escalationCeiling %}<tr><th>{{ labels.escalationCeiling }}</th><td>{{ scenario.scenario.escalationCeiling }}</td></tr>{% endif %}
{%- if scenario.scenario.ending %}<tr><th>{{ labels.ending }}</th><td>{{ scenario.scenario.ending }}</td></tr>{% endif %}
{%- if scenario.scenario.redHerring %}<tr><th>{{ labels.redHerring }}</th><td>{{ scenario.scenario.redHerring }}</td></tr>{% endif %}
{%- if scenario.scenario.realVsFictional %}<tr><th>{{ labels.realVsFictional }}</th><td>{{ scenario.scenario.realVsFictional }}</td></tr>{% endif %}
{%- if scenario.scenario.symmetry %}<tr><th>{{ labels.symmetry }}</th><td>{{ scenario.scenario.symmetry }}</td></tr>{% endif %}
</table>
{%- endif %}
{%- if scenario.groundTruth %}

<h2>Ground Truth</h2>
<ol>
{%- for g in scenario.groundTruth %}
<li><strong>{{ g.id }}</strong> {{ g.text }}</li>
{%- endfor %}
</ol>
{%- endif %}
{%- if scenario.names or scenario.vocabulary %}

<h2>Names and Vocabulary</h2>
<table>
{%- if scenario.names.exercise %}<tr><th>{{ labels.exerciseName }}</th><td>{{ scenario.names.exercise }}</td></tr>{% endif %}
{%- if scenario.names.organizations %}<tr><th>{{ labels.organizations }}</th><td>{{ scenario.names.organizations | join: "; " }}</td></tr>{% endif %}
{%- if scenario.names.actor %}<tr><th>{{ labels.actorName }}</th><td>{{ scenario.names.actor }}</td></tr>{% endif %}
{%- if scenario.names.nationalBodies %}<tr><th>{{ labels.nationalBodies }}</th><td>{{ scenario.names.nationalBodies }}</td></tr>{% endif %}
{%- if scenario.names.publicHandles %}<tr><th>{{ labels.publicHandles }}</th><td>{{ scenario.names.publicHandles }}</td></tr>{% endif %}
{%- if scenario.vocabulary.fixed %}<tr><th>{{ labels.fixedTerms }}</th><td>{{ scenario.vocabulary.fixed | join: "; " }}</td></tr>{% endif %}
{%- if scenario.vocabulary.banned %}<tr><th>{{ labels.bannedTerms }}</th><td>{{ scenario.vocabulary.banned | join: "; " }}</td></tr>{% endif %}
</table>
{%- endif %}
{%- if scenario.decisions %}

<h2>Decisions</h2>
<table>
<tr><th>Question</th><th>Answer</th><th>Who</th><th>Why</th></tr>
{%- for d in scenario.decisions %}
{%- assign type = d.value | object.typeof %}
<tr><td>{{ labels[d.question] }}</td><td>{% if type == "array" %}{{ d.value | join: "; " }}{% else %}{{ d.value }}{% endif %}</td><td>{% if d.who == "proposed" %}Proposed by {% if d.via == "agent" %}the agent{% else %}{{ d.by }}{% endif %}{% else %}Stated by {{ d.by }}{% endif %}</td><td>{{ d.reason }}</td></tr>
{%- endfor %}
</table>
{%- endif %}
{%- if scenario.findings %}

<h2>Open Findings</h2>
<ul>
{%- for f in scenario.findings %}
<li>Stage {{ f.stage }}: {{ f.message }}</li>
{%- endfor %}
</ul>
{%- endif %}

